// Unified OctavianOS / Chimera II OS branding resource.
// Generated from assets/branding/unified-master-logo.svg.
// This immutable SVG data URI is for consumers with SVG support; it does not
// itself render a framebuffer splash. Use a raster renderer for early boot.
#include <stddef.h>
extern "C" {
extern const char UNIFIED_MASTER_LOGO_DATA_URI[] = "data:image/svg+xml;base64,";
extern const size_t UNIFIED_MASTER_LOGO_SIZE = sizeof(UNIFIED_MASTER_LOGO_DATA_URI) - 1;
const char* get_unified_system_logo(void) { return UNIFIED_MASTER_LOGO_DATA_URI; }
size_t get_unified_system_logo_size(void) { return UNIFIED_MASTER_LOGO_SIZE; }
}
